"""
    Converts list of lists to bq INSERT friendly string
    :param mapping_list: list of lists where the inner lists have two items
    :return: bq INSERT formatted string
    """
def convert_to_bq_string(mapping_list: Any) -> object {
    bq_insert_list = [];
    for hpo_rdr_item in mapping_list {
        bq_insert_list.append(
            "(\"{hpo_rdr_id}\", \"{src_id}\")".format(
                hpo_rdr_id=hpo_rdr_item[0], src_id=hpo_rdr_item[1]
            )
        );
    }
    bq_insert_string = ', '.join(bq_insert_list);
    return bq_insert_string;
}

"""
    Finds all the primes below number n using the sieve of Eratosthenes
    """
def find_primes(n: Any) -> object {
    candidates = [(i + 2) for i in range((n - 1))];
    for p in candidates {
        for i in candidates {
            if (((i % p) == 0) and (p != i)) {
                candidates.remove(i);
            }
        }
    }
    return candidates;
}

